/// <summary>
/// PricingAttribute of table <c>InventTable</c> field PdsCWWMSQtyPerLayer.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTablePdsCWWMSQtyPerLayer extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, PdsCWWMSQtyPerLayer);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by PdsCWWMSQtyPerLayer
    {
        if (! ret.in(inventTable.PdsCWWMSQtyPerLayer))
        {
            ret.add(inventTable.PdsCWWMSQtyPerLayer);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, PdsCWWMSQtyPerLayer));
    qbr.value(queryValue(_value));
}
